<?php $badge = function ($s) { include APP_ROOT . '/views/partials/status.php'; }; ?>
<div class="topbar"><div><a class="small" href="/portal/projects">← Projects</a><h1><?= e($p['title']) ?></h1><span class="muted small"><?= e($p['number']) ?></span></div><div class="row"><?php $badge($p['status']); ?><b><?= (int)$p['progress'] ?>%</b></div></div>
<?php if ($p['status'] === 'awaiting_requirements'): ?><div class="alert alert-warn">We need a few details before we can start. <a class="btn btn-primary btn-sm" href="/portal/projects/<?= e($p['number']) ?>/requirements">Complete requirements</a></div><?php endif; ?>
<div class="progress" style="margin-bottom:20px"><span style="width:<?= (int)$p['progress'] ?>%"></span></div>
<div class="grid g2" style="align-items:start">
  <div class="panel"><h2>Milestones</h2><?php foreach ($milestones as $m): ?><div class="ms<?= $m['status'] === 'done' ? ' done' : '' ?>"><span class="st"></span><span><?= e($m['title']) ?></span><?php if ($m['agent_slug'] === 'customer' && $m['status'] !== 'done'): ?><span class="badge b-amber" style="margin-left:auto">your step</span><?php elseif ($m['agent_slug'] === 'owner' && $m['status'] !== 'done'): ?><span class="badge" style="margin-left:auto">human approval</span><?php endif; ?></div><?php endforeach; ?>
    <?php if ($deliverables): ?><h2 style="margin-top:18px">Deliverables for review</h2><?php foreach ($deliverables as $d): ?><details class="card flat" style="margin-bottom:10px"><summary><b><?= e($d['title']) ?></b> <?php $badge($d['status']); ?></summary><pre style="background:var(--surface);color:var(--ink);margin-top:10px"><?= e($d['body']) ?></pre>
      <?php if (in_array($d['status'], ['ready', 'delivered'], true)): ?><form method="post" action="/portal/projects/<?= e($p['number']) ?>/deliverable" class="stack"><?= App\Csrf::field() ?><input type="hidden" name="id" value="<?= (int)$d['id'] ?>"><textarea name="feedback" placeholder="Changes you'd like (only needed if requesting changes)" style="min-height:70px"></textarea><div class="row"><button class="btn btn-success btn-sm" name="decision" value="approve">Approve</button><button class="btn btn-ghost btn-sm" name="decision" value="revise">Request changes</button></div></form><?php endif; ?></details><?php endforeach; endif; ?>
    <?php if ($docs): ?><h2 style="margin-top:18px">Files</h2><?php foreach ($docs as $d): ?><div class="small" style="padding:4px 0"><a href="/documents/<?= (int)$d['id'] ?>"><?= e($d['filename']) ?></a> <span class="muted">· <?= round($d['size_bytes'] / 1024) ?> KB</span></div><?php endforeach; endif; ?>
  </div>
  <div class="panel"><h2>Activity</h2><?php if (!$activity): ?><div class="empty">No activity yet.</div><?php endif; ?><ul class="timeline"><?php foreach ($activity as $a): ?><li><time><?= e(substr($a['created_at'], 0, 16)) ?> UTC · <?= e($a['actor'] === 'customer' ? 'You' : ($a['actor'] === 'system' ? '818' : (str_contains($a['actor'], 'team') || $a['actor'] === 'owner' ? '818 team' : '818 AI'))) ?></time><?= e($a['summary']) ?></li><?php endforeach; ?></ul></div>
</div>
<?php if ($p['status'] === 'completed' && !$reviewed): ?><div class="panel" id="feedback"><h2>How did we do?</h2><form method="post" action="/portal/projects/<?= e($p['number']) ?>/feedback"><?= App\Csrf::field() ?>
  <div class="row"><?php for ($i = 5; $i >= 1; $i--): ?><label class="check"><input type="radio" name="rating" value="<?= $i ?>" required> <?= $i ?>★</label><?php endfor; ?></div>
  <div class="field" style="margin-top:10px"><textarea name="body" placeholder="Tell us about your experience"></textarea></div><div class="field"><input type="text" name="display_name" placeholder="Name to show if published (optional)"></div>
  <label class="check"><input type="checkbox" name="consent_publish" value="1"> You may publish this review on your website</label><button class="btn btn-primary" style="margin-top:10px">Send feedback</button></form></div><?php endif; ?>
